<template>
  <section class="archive-editor">
    <header class="editor-heading"><div><h2>赛事档案</h2><p>选择赛事，维护介绍、历年资料和图片。</p></div><div class="heading-actions"><span v-if="dirty" class="unsaved">有未保存的修改</span><button v-if="dirty" type="button" :disabled="busy || uploading" @click="discard">放弃修改</button><button class="primary" type="button" :disabled="!draft || busy || uploading || !dirty" @click="save">{{ busy ? '保存中…' : '保存修改' }}</button></div></header>
    <p v-if="message" class="notice" role="status">{{ message }}</p><p v-if="error" class="error" role="alert">{{ error }} <button type="button" @click="reload">重新加载</button></p>
    <div class="workspace">
      <aside class="sidebar"><label>赛事<select :value="raceId" :disabled="busy || loading || uploading" @change="requestRace"><option v-for="item in races" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div v-if="pendingRace" class="switch-warning"><p>当前修改尚未保存。</p><button type="button" @click="discardSwitch">放弃修改并切换</button><button type="button" @click="pendingRace=''">继续编辑</button></div><nav v-if="draft" aria-label="档案编辑栏目"><button v-for="item in tabs" :key="item.id" type="button" :class="{selected:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="tab=item.id"><span>{{ item.label }}</span><span aria-hidden="true">›</span></button></nav></aside>
      <div v-if="loading" class="empty" role="status">正在读取档案…</div><div v-else-if="!draft" class="empty">选择赛事开始编辑</div>
      <fieldset v-else class="editor-main" :disabled="busy || uploading">
        <div class="editor-title"><div><span class="eyebrow">{{ draft.race.name }}</span><h3>{{ tabs.find(t=>t.id===tab)?.label }}</h3></div><div v-if="annualTabs.includes(tab)" class="year-control"><label>编辑年份<select v-model="year"><option v-for="e in sortedEditions" :key="e.year" :value="String(e.year)">{{ e.year }} 年</option></select></label><button type="button" @click="addingYear=!addingYear">新增年份</button></div></div>
        <form v-if="addingYear && annualTabs.includes(tab)" class="add-year" @submit.prevent="addYear"><label>年份<input v-model="newYear" inputmode="numeric" maxlength="4" placeholder="例如 2026" /></label><button type="submit">添加</button><button type="button" @click="addingYear=false">取消</button></form>
        <template v-if="tab==='basic'"><div class="form-grid"><label v-for="f in raceFields" :key="f.key">{{ f.label }}<input v-model="draft.race[f.key]" :maxlength="f.max" /></label><label>创办年份<input v-model="draft.archive.profile.foundingYear" maxlength="4" inputmode="numeric" /></label></div><label class="field">赛事介绍<textarea v-model="draft.archive.intro" rows="5" maxlength="12000" /></label><div class="media-section"><h4>赛事封面</h4><p>封面展示在赛事专题顶部。</p><div v-if="draft.archive.hero.imageUrl" class="hero-preview"><img :src="draft.archive.hero.imageUrl" alt="当前赛事封面" /><button type="button" @click="draft.archive.hero.imageUrl=''">移除</button></div><label class="upload">{{ uploading ? '正在上传…' : '上传封面图片' }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="uploadSingle($event,draft.archive.hero,'imageUrl')" /></label><label class="field">图片说明<input v-model="draft.archive.hero.alt" maxlength="240" placeholder="例如：赛事起跑现场" /></label></div><div class="list-heading"><h4>赛事看点</h4><button type="button" @click="draft.archive.highlights.push({title:'',body:''})">添加看点</button></div><div v-for="(highlight,i) in draft.archive.highlights" :key="i" class="repeat"><div class="repeat-head"><strong>看点 {{ i+1 }}</strong><button type="button" @click="draft.archive.highlights.splice(i,1)">移除</button></div><label class="field">标题<input v-model="highlight.title" maxlength="160" /></label><label class="field">介绍<textarea v-model="highlight.body" rows="3" maxlength="4000" /></label></div></template>
        <template v-if="edition && tab==='route'"><div class="form-grid"><label>比赛日期<input v-model="edition.date" type="date" /></label><label>比赛项目<input v-model="edition.distance" placeholder="全程马拉松" /></label><label>起点<input v-model="edition.route.start" /></label><label>终点<input v-model="edition.route.finish" /></label><label>路线版本名称<input v-model="edition.route.versionTitle" placeholder="例如：奥林匹克公园终点版" /></label></div><label class="field">途经路线<textarea v-model="edition.route.summary" rows="3" placeholder="按道路顺序填写" /></label><label class="field">路线变化<textarea v-model="edition.route.changes" rows="3" /></label><label class="field">赛道分析<textarea :value="joinLines(edition.route.analysis)" rows="4" placeholder="每行一条" @input="edition.route.analysis=splitLines($event.target.value)" /></label><div class="media-section"><h4>路线图</h4><div v-if="edition.route.mapUrl" class="hero-preview"><img :src="edition.route.mapUrl" alt="路线图" /><button type="button" @click="edition.route.mapUrl=''">移除</button></div><label class="upload">上传路线图<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="uploadSingle($event,edition.route,'mapUrl')" /></label></div><details class="group"><summary>管理路线版本分组</summary><div class="group-inner"><p class="hint">将确认一致或相近的年份放入一组。相同道路描述不代表完整赛道相同。</p><button type="button" @click="draft.archive.routeGroups.push({id:'route-'+Date.now(),title:'',years:[],note:'',match:'similar'})">添加版本组</button><div v-for="(g,i) in draft.archive.routeGroups" :key="g.id" class="repeat"><div class="repeat-head"><strong>版本 {{ i+1 }}</strong><button type="button" @click="draft.archive.routeGroups.splice(i,1)">移除</button></div><label class="field">版本名称<input v-model="g.title" /></label><label class="field">适用年份<input :value="g.years.join('、')" placeholder="2025、2026" @input="g.years=$event.target.value.split(/[,，、\s]+/).filter(Boolean)" /></label><label class="field">版本关系<select v-model="g.match"><option value="similar">相近路线</option><option value="exact">已确认相同路线</option></select></label><label class="field">版本说明<textarea v-model="g.note" rows="3" /></label></div></div></details></template>
        <template v-if="edition && tab==='entry'"><h4>报名与中签</h4><div class="form-grid"><label v-for="f in registrationFields" :key="f.key">{{ f.label }}<textarea v-model="edition.registration[f.key]" :rows="f.long?3:2" /></label></div><h4 class="section-title">参赛指南</h4><details v-for="group in logisticsFields" :key="group.key" class="group" open><summary>{{ group.label }}</summary><div class="form-grid"><label v-for="f in group.fields" :key="f.key">{{ f.label }}<textarea v-model="edition.logistics[group.key][f.key]" rows="3" /></label></div></details></template>
        <template v-if="edition && tab==='results'"><h4>参赛与完赛</h4><div class="form-grid"><label v-for="f in participationFields" :key="f.key">{{ f.label }}<input v-model="edition.participation[f.key]" /></label></div><label class="field">统计说明<textarea v-model="edition.participation.note" rows="3" /></label><div class="list-heading"><h4>成绩</h4><button type="button" @click="edition.results.push({group:'',athlete:'',time:'',timing:'',sourceIds:[]})">添加成绩</button></div><p v-if="!edition.results.length" class="hint">还没有成绩记录。</p><div v-for="(result,index) in edition.results" :key="index" class="repeat"><div class="repeat-head"><strong>成绩 {{ index+1 }}</strong><button type="button" @click="edition.results.splice(index,1)">移除</button></div><div class="form-grid"><label>组别<input v-model="result.group" placeholder="例如男子冠军" /></label><label>选手<input v-model="result.athlete" /></label><label>成绩<input v-model="result.time" placeholder="02:03:10" /></label><label>计时口径<input v-model="result.timing" placeholder="枪时 / 净计时" /></label></div></div></template>
        <template v-if="edition && tab==='gear'"><div class="subtabs"><button v-for="name in gearTypes" :key="name" type="button" :class="{selected:gearType===name}" @click="gearType=name">{{ name }}</button></div><template v-if="gear"><label class="field">名称<input v-model="gear.name" /></label><label class="field">介绍与设计说明<textarea v-model="gear.description" rows="4" /></label><label class="field">物品清单<textarea :value="joinLines(gear.items)" rows="4" placeholder="每行一项" @input="gear.items=splitLines($event.target.value)" /></label><div class="media-section"><h4>{{ gearType }}图片</h4><p>第一张为封面，可添加正面、背面和细节。</p><div class="image-grid"><div v-for="(image,index) in gear.images" :key="image.url" class="image-item"><img :src="image.url" :alt="image.caption || gearType" /><span v-if="index===0" class="cover">封面</span><input v-model="image.caption" aria-label="图片说明" placeholder="图片说明" /><div><button type="button" :disabled="index===0" @click="move(gear.images,index,-1)" aria-label="向前移动">←</button><button type="button" :disabled="index===gear.images.length-1" @click="move(gear.images,index,1)" aria-label="向后移动">→</button><button type="button" @click="gear.images.splice(index,1)">移除</button></div></div></div><label class="upload">{{ uploading ? '正在上传…' : '添加图片' }}<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="uploadMany($event,gear.images)" /></label></div></template></template>
        <template v-if="tab==='albums'"><div class="list-heading"><p class="hint">按年份整理赛事照片，第一张为封面。</p><button type="button" @click="addAlbum">新增相册</button></div><div v-if="!draft.archive.photoAlbums.length" class="empty small">还没有年度相册</div><div v-for="(album,index) in draft.archive.photoAlbums" :key="album.id" class="repeat"><div class="repeat-head"><strong>相册 {{ index+1 }}</strong><button type="button" @click="draft.archive.photoAlbums.splice(index,1)">移除相册</button></div><div class="form-grid"><label>年份<input v-model="album.year" maxlength="4" inputmode="numeric" /></label><label>相册名称<input v-model="album.title" /></label></div><div class="image-grid"><div v-for="(image,i) in album.media" :key="image.url" class="image-item"><img :src="image.url" :alt="image.caption || album.title" /><span v-if="i===0" class="cover">封面</span><input v-model="image.caption" aria-label="图片说明" placeholder="图片说明" /><div><button type="button" :disabled="i===0" @click="move(album.media,i,-1)" aria-label="向前移动">←</button><button type="button" :disabled="i===album.media.length-1" @click="move(album.media,i,1)" aria-label="向后移动">→</button><button type="button" @click="album.media.splice(i,1)">移除</button></div></div></div><label class="upload">添加照片<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="uploadMany($event,album.media)" /></label></div></template>
        <template v-if="tab==='updates' || tab==='news'"><div class="list-heading"><p class="hint">{{ tab==='updates' ? '记录赛事故事和有趣的细节。' : '发布赛事公告、报道和最新消息。' }}</p><button type="button" @click="addArticle">新增{{ tab==='updates'?'新鲜事':'新闻' }}</button></div><div v-if="!draft.archive[tab].length" class="empty small">还没有内容</div><div v-for="(article,index) in draft.archive[tab]" :key="article.id" class="repeat"><div class="repeat-head"><strong>{{ article.title || '新内容' }}</strong><button type="button" @click="draft.archive[tab].splice(index,1)">移除</button></div><label class="field">标题<input v-model="article.title" maxlength="160" /></label><div class="form-grid"><label>相关年份<input v-model="article.editionYear" maxlength="4" /></label><label>发布日期<input v-model="article.publishedAt" type="date" /></label><label>分类标签<input v-model="article.tag" maxlength="40" placeholder="例如：赛事故事" /></label></div><label class="field">摘要<textarea v-model="article.summary" rows="2" maxlength="1200" /></label><label class="field">正文<textarea v-model="article.body" rows="5" maxlength="20000" /></label><div class="image-grid"><div v-for="(image,i) in article.images" :key="image.url" class="image-item"><img :src="image.url" :alt="image.caption || article.title" /><input v-model="image.caption" maxlength="240" aria-label="图片说明" placeholder="图片说明" /><div><button type="button" :disabled="i===0" @click="move(article.images,i,-1)" aria-label="向前移动">←</button><button type="button" :disabled="i===article.images.length-1" @click="move(article.images,i,1)" aria-label="向后移动">→</button><button type="button" @click="article.images.splice(i,1)">移除</button></div></div></div><label class="upload">添加内容图片<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="uploadMany($event,article.images)" /></label></div><details v-if="tab==='updates' && draft.archive.stories.length" class="group"><summary>已有赛事故事 · {{ draft.archive.stories.length }} 篇</summary><div class="group-inner"><div v-for="(story,i) in draft.archive.stories" :key="i" class="repeat"><div class="repeat-head"><strong>赛事故事 {{ i+1 }}</strong><button type="button" @click="draft.archive.stories.splice(i,1)">移除</button></div><label class="field">标题<input v-model="story.title" maxlength="160" /></label><label class="field">正文<textarea v-model="story.body" rows="5" maxlength="20000" /></label></div></div></details></template>
        <p v-if="annualTabs.includes(tab) && !edition" class="empty small">请先添加年份。</p>
        <div class="savebar"><label><input type="checkbox" v-model="mediaConfirmed" /> 确认已上传的图片可在本站展示</label><button class="primary" type="button" :disabled="!dirty || busy || uploading" @click="save">{{ busy ? '保存中…' : '保存修改' }}</button></div>
      </fieldset>
    </div>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { adminUpload } from '../../api';
const props=defineProps({sessionToken:String,request:Function,refreshKey:[Number,String]});
const tabs=[{id:'basic',label:'基本信息'},{id:'route',label:'赛道'},{id:'entry',label:'报名参赛'},{id:'results',label:'成绩'},{id:'gear',label:'赛事物品'},{id:'albums',label:'年度相册'},{id:'updates',label:'新鲜事'},{id:'news',label:'新闻'}];
const annualTabs=['route','entry','results','gear'],gearTypes=['参赛服','奖牌','参赛包','完赛包'];
const raceFields=[{key:'name',label:'赛事名称',max:80},{key:'shortName',label:'简称',max:30},{key:'city',label:'举办城市',max:40},{key:'tagline',label:'赛事一句话',max:160},{key:'summary',label:'简要介绍',max:1200}];
const registrationFields=[['method','报名方式',1],['opens','报名开始'],['closes','报名截止'],['drawDate','抽签公布'],['fee','报名费用'],['qualification','报名资格',1],['applicants','报名人数'],['eligibleApplicants','有效报名人数'],['lotteryPool','抽签池人数'],['drawQuota','抽签名额'],['directQuota','直通名额'],['lotteryRate','公布中签率'],['lotteryNote','中签口径',1],['note','其他说明',1]].map(([key,label,long])=>({key,label,long}));
const participationFields=[['planned','计划规模'],['starters','实际起跑'],['finishers','完赛人数'],['finishRate','完赛率']].map(([key,label])=>({key,label}));
const logisticsFields=[['collection','领物安排',[['time','领物时间'],['place','领物地点'],['requirements','领取要求']]],['transport','交通与离场',[['start','前往起点'],['finish','终点离场'],['expo','领物交通']]],['raceDay','比赛日服务',[['startTime','发枪与分区'],['timeLimit','关门安排'],['bagDrop','存取包'],['aidStations','补给与饮水'],['toilets','卫生间'],['medical','医疗服务']]]].map(([key,label,fields])=>({key,label,fields:fields.map(([key,label])=>({key,label}))}));
const races=ref([]),raceId=ref(''),pendingRace=ref(''),draft=ref(null),snapshot=ref(''),year=ref(''),tab=ref('basic'),gearType=ref('参赛服'),newYear=ref(''),addingYear=ref(false),loading=ref(false),busy=ref(false),uploading=ref(false),error=ref(''),message=ref(''),mediaConfirmed=ref(false);let seq=0,disposed=false;
const dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==snapshot.value);
const sortedEditions=computed(()=>[...(draft.value?.archive.editions||[])].sort((a,b)=>Number(b.year)-Number(a.year)));
const edition=computed(()=>draft.value?.archive.editions.find(e=>String(e.year)===String(year.value)));
const gear=computed(()=>edition.value?.gear.find(g=>g.category===gearType.value));
function splitLines(v){return v.split('\n').map(s=>s.trim()).filter(Boolean)}function joinLines(v){return (v||[]).join('\n')}
function normalizeEdition(e){e.year=String(e.year);e.route={summary:'',start:'',finish:'',changes:'',analysis:[],mapUrl:'',sourceIds:[],...e.route};e.registration={sourceIds:[],...e.registration};for(const f of registrationFields)e.registration[f.key]??='';e.participation={sourceIds:[],...e.participation};for(const f of participationFields)e.participation[f.key]??='';e.participation.note??='';e.logistics=e.logistics||{};for(const g of logisticsFields){e.logistics[g.key]={sourceIds:[],...e.logistics[g.key]};for(const f of g.fields)e.logistics[g.key][f.key]??='';}e.results=e.results||[];e.gear=e.gear||[];for(const category of gearTypes){let g=e.gear.find(item=>item.category===category);if(!g){g={category,name:'',description:'',items:[],imageUrl:'',sourceIds:[],images:[]};e.gear.push(g)}g.items=g.items||[];g.images=Array.isArray(g.images)?g.images:[];}return e;}
function normalize(data){const a=data.archive;const r=data.race;a.profile={foundingYear:'',...a.profile};a.hero={imageUrl:'',alt:'',...a.hero};a.highlights=a.highlights||[];a.routeGroups=a.routeGroups||[];a.stories=a.stories||[];a.editions=(a.editions||[]).map(normalizeEdition);a.photoAlbums=(a.photoAlbums||[]).map(x=>({...x,year:String(x.year||''),media:x.media||[]}));a.updates=(a.updates||[]).map(x=>({...x,images:x.images||[]}));a.news=(a.news||[]).map(x=>({...x,images:x.images||[]}));return {race:r,archive:a};}
async function list(){try{const result=await props.request('/admin/race-archives');if(disposed)return;races.value=result.races||[];if(races.value.length)await load(races.value[0].id);}catch(e){error.value=e.message;}}
async function load(id){const ticket=++seq;loading.value=true;error.value='';try{const data=await props.request('/admin/race-archives/'+encodeURIComponent(id));if(disposed||ticket!==seq)return;draft.value=normalize(data);raceId.value=id;year.value=String(sortedEditions.value[0]?.year||'');snapshot.value=JSON.stringify(draft.value);mediaConfirmed.value=false;pendingRace.value='';message.value='';}catch(e){if(ticket===seq)error.value=e.message;}finally{if(ticket===seq)loading.value=false;}}
function requestRace(event){const id=event.target.value;event.target.value=raceId.value;if(id===raceId.value)return;if(dirty.value){pendingRace.value=id;return;}load(id)}function discardSwitch(){load(pendingRace.value)}function reload(){if(dirty.value){error.value='请先保存当前修改，再重新加载。';return;}raceId.value?load(raceId.value):list();}
function discard(){if(busy.value||uploading.value)return;draft.value=JSON.parse(snapshot.value);pendingRace.value='';error.value='';message.value='已放弃本次修改。';}
function addYear(){if(!/^\d{4}$/.test(newYear.value)||Number(newYear.value)<1900||Number(newYear.value)>2100){error.value='请输入 1900 至 2100 之间的年份。';return;}if(draft.value.archive.editions.some(e=>String(e.year)===newYear.value)){error.value='该年份已存在。';return;}draft.value.archive.editions.push(normalizeEdition({year:newYear.value,date:'',distance:'',route:{},registration:{},participation:{},logistics:{},results:[],gear:[],notes:[]}));year.value=newYear.value;newYear.value='';addingYear.value=false;error.value='';}
function move(items,index,by){const to=index+by;if(to<0||to>=items.length)return;items.splice(to,0,items.splice(index,1)[0]);}
async function uploadFiles(event,done,max=1){const files=[...event.target.files];event.target.value='';if(!files.length||busy.value||uploading.value)return;if(files.length>max){error.value='每组最多上传 30 张图片。';return;}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)){error.value='请上传 JPG、PNG 或 WebP 图片，每张不超过 8MB。';return;}const ticket=seq;uploading.value=true;error.value='';try{for(const file of files){const data=await adminUpload('/admin/race-archives/'+encodeURIComponent(raceId.value)+'/images',file,props.sessionToken);if(disposed||ticket!==seq)return;done(data.url);}}catch(e){if(!disposed&&ticket===seq)error.value=e.message;}finally{if(!disposed)uploading.value=false;}}
function uploadSingle(event,obj,key){return uploadFiles(event,url=>obj[key]=url)}function uploadMany(event,items){return uploadFiles(event,url=>items.push({url,caption:''}),30-items.length)}
function addAlbum(){draft.value.archive.photoAlbums.unshift({id:'album-'+Date.now(),year:year.value||'',title:'',media:[]})}function addArticle(){draft.value.archive[tab.value].unshift({id:tab.value+'-'+Date.now(),title:'',editionYear:'',publishedAt:'',tag:'',summary:'',body:'',images:[]})}
async function save(){if(busy.value||uploading.value||!draft.value)return;busy.value=true;error.value='';message.value='';const ticket=seq;try{for(const e of draft.value.archive.editions)for(const g of e.gear)g.imageUrl=g.images?.[0]?.url||'';const result=await props.request('/admin/race-archives/'+encodeURIComponent(raceId.value),{method:'PUT',body:JSON.stringify({...draft.value,mediaConfirmed:mediaConfirmed.value})});if(disposed||ticket!==seq)return;draft.value=normalize(result);snapshot.value=JSON.stringify(draft.value);message.value='已保存赛事档案。';}catch(e){if(!disposed&&ticket===seq)error.value=e.message;}finally{if(!disposed)busy.value=false;}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue='';}}window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{disposed=true;seq++;window.removeEventListener('beforeunload',beforeUnload)});watch(()=>props.sessionToken,()=>{seq++;draft.value=null;races.value=[];raceId.value='';list()});watch(()=>props.refreshKey,()=>{if(!busy.value&&!uploading.value)reload()});defineExpose({hasUnsavedChanges:()=>dirty.value||uploading.value||busy.value});list();
